-- Flyway V1 baseline for TravelCRM.
-- Promoted verbatim from db/proposed/V1_PROPOSED__baseline_schema.sql (kept there as the review
-- record). Generated from the JPA entity model plus the final-state supplementary DDL in
-- db/indexes.sql. Excludes legacy data backfills, demo seed data, and runtime bootstrap data.
--
-- TWO WAYS THIS FILE IS USED, and they are not the same:
--
--   FRESH database  — Flyway EXECUTES this, then every later V. Deploy with FLYWAY_ENABLED=true,
--                     FLYWAY_BASELINE_ON_MIGRATE=false, JPA_DDL_AUTO=validate, SQL_INIT_MODE=never.
--
--   EXISTING pilot  — Flyway STAMPS it (baseline-on-migrate) and never runs a line of it. The
--                     assertion being made is "the live schema already looks like this file"; the
--                     stamp itself verifies NOTHING. What verifies it is
--                     scripts/predeploy-flyway-shadow-check.ps1 -CloneTargetSchema
--                     -BaselineExistingSchema, which clones the real schema, stamps, applies the
--                     pending Vs and runs Hibernate validate against the result. Run it, and take a
--                     restore-tested pg_dump, BEFORE the adoption deploy. See docs/DEPLOYMENT.md.
--
-- This file deliberately predates leads.lead_code — that change is V2, so both paths converge:
-- a fresh database gets V1+V2, and the live pilot (whose schema matches V1 today) gets V2 applied
-- on top of the stamp. Do not fold V2 back into here.
--
-- NEVER edit this file once it has been applied or stamped anywhere shared — that changes its
-- checksum and every subsequent Flyway validate fails. Corrections go in a new V.

CREATE SEQUENCE IF NOT EXISTS revinfo_seq start with 1 increment by 50;
CREATE TABLE IF NOT EXISTS accounting_settings (id bigint generated by default as identity, created_at timestamp(6) not null, created_by varchar(255), deleted_at timestamp(6), deleted_by varchar(255), public_id uuid not null unique, updated_at timestamp(6) not null, updated_by varchar(255), tenant_id bigint not null, auto_tcs_on_overseas boolean not null, gst_scheme varchar(20) not null check (gst_scheme in ('REGULAR','COMPOSITION','UNREGISTERED')), input_tax_credit_eligible boolean not null, round_invoice_total boolean not null, primary key (id), constraint uq_accounting_settings_tenant unique (tenant_id));
CREATE TABLE IF NOT EXISTS activity_logs (id bigint generated by default as identity, created_at timestamp(6) not null, created_by varchar(255), deleted_at timestamp(6), deleted_by varchar(255), public_id uuid not null unique, updated_at timestamp(6) not null, updated_by varchar(255), tenant_id bigint not null, user_id bigint, action varchar(20) not null check (action in ('Login','Logout','Create','Update','Delete','Settings','Export','View')), description TEXT, ip_address varchar(45), user_agent varchar(500), user_email varchar(150), user_name varchar(150), user_type varchar(20), primary key (id));
CREATE TABLE IF NOT EXISTS addons (id bigint generated by default as identity, created_at timestamp(6) not null, created_by varchar(255), deleted_at timestamp(6), deleted_by varchar(255), public_id uuid not null unique, updated_at timestamp(6) not null, updated_by varchar(255), tenant_id bigint not null, active boolean not null, description TEXT, name varchar(200) not null, price numeric(12,2), city_id bigint, primary key (id));
CREATE TABLE IF NOT EXISTS ai_audit_logs (id bigint generated by default as identity, created_at timestamp(6) not null, created_by varchar(255), deleted_at timestamp(6), deleted_by varchar(255), public_id uuid not null unique, updated_at timestamp(6) not null, updated_by varchar(255), tenant_id bigint not null, latency_ms bigint, outcome TEXT, prompt TEXT, session_id bigint, status varchar(20) check (status in ('SUCCESS','ERROR','DENIED')), tool_name varchar(120), tool_params TEXT, user_id bigint, primary key (id));
CREATE TABLE IF NOT EXISTS ai_chat_messages (id bigint generated by default as identity, created_at timestamp(6) not null, created_by varchar(255), deleted_at timestamp(6), deleted_by varchar(255), public_id uuid not null unique, updated_at timestamp(6) not null, updated_by varchar(255), tenant_id bigint not null, content TEXT, role varchar(20) not null check (role in ('USER','ASSISTANT','SYSTEM','TOOL')), session_id bigint not null, tool_name varchar(120), primary key (id));
CREATE TABLE IF NOT EXISTS ai_chat_sessions (id bigint generated by default as identity, created_at timestamp(6) not null, created_by varchar(255), deleted_at timestamp(6), deleted_by varchar(255), public_id uuid not null unique, updated_at timestamp(6) not null, updated_by varchar(255), tenant_id bigint not null, last_message_at timestamp(6), title varchar(200), user_id bigint not null, primary key (id));
CREATE TABLE IF NOT EXISTS airlines (id bigint generated by default as identity, created_at timestamp(6) not null, created_by varchar(255), deleted_at timestamp(6), deleted_by varchar(255), public_id uuid not null unique, updated_at timestamp(6) not null, updated_by varchar(255), tenant_id bigint not null, country varchar(100), fleet varchar(200), iata varchar(10), logo varchar(500), name varchar(200) not null, status varchar(50), city_id bigint, primary key (id));
CREATE TABLE IF NOT EXISTS announcements (id bigint generated by default as identity, created_at timestamp(6) not null, created_by varchar(255), deleted_at timestamp(6), deleted_by varchar(255), public_id uuid not null unique, updated_at timestamp(6) not null, updated_by varchar(255), audience varchar(20) not null check (audience in ('ALL','ACTIVE','TRIAL')), message TEXT not null, recipient_count integer not null, recipient_scope varchar(20) not null check (recipient_scope in ('ADMINS','ALL_USERS')), sent_by_email varchar(150), tenant_count integer not null, title varchar(200) not null, primary key (id));
CREATE TABLE IF NOT EXISTS billing_records (id bigint generated by default as identity, created_at timestamp(6) not null, created_by varchar(255), deleted_at timestamp(6), deleted_by varchar(255), public_id uuid not null unique, updated_at timestamp(6) not null, updated_by varchar(255), amount numeric(12,2) not null, currency varchar(8), due_date date, invoice_number varchar(30) not null, issue_date date not null, notes varchar(500), paid_date date, period_end date, period_start date, plan varchar(20) check (plan in ('STARTER','PRO','ENTERPRISE')), status varchar(16) not null check (status in ('UNPAID','PAID','VOID','CREDIT')), tenant_code varchar(50), tenant_id bigint not null, tenant_name varchar(150), upgrade_to_plan varchar(20) check (upgrade_to_plan in ('STARTER','PRO','ENTERPRISE')), primary key (id), constraint uq_billing_invoice_number unique (invoice_number));
CREATE TABLE IF NOT EXISTS booking_cancellations (id bigint generated by default as identity, created_at timestamp(6) not null, created_by varchar(255), deleted_at timestamp(6), deleted_by varchar(255), public_id uuid not null unique, updated_at timestamp(6) not null, updated_by varchar(255), tenant_id bigint not null, applied_band_min_days integer, applied_deduction_type varchar(10) check (applied_deduction_type in ('PERCENT','FLAT')), applied_deduction_value numeric(12,2), base_considered numeric(12,2), booking_code varchar(20), booking_id bigint not null, cancel_date date not null, cancel_scope varchar(10) not null check (cancel_scope in ('FULL','PARTIAL')), cancelled_at timestamp(6) not null, cancelled_by_email varchar(255), cancelled_by_user_id bigint, credit_note_doc_public_id uuid, credit_note_number varchar(30), customer_balance_owed numeric(12,2), customer_owes boolean not null, days_before_departure integer, final_charge_base numeric(12,2), gst_on_charge numeric(12,2), lead_action varchar(30) check (lead_action in ('MOVE_TO_LEAD','PERMANENT_DELETE_LEAD')), no_policy boolean not null, overridden_by_user_id bigint, override_applied boolean not null, override_reason TEXT, paid_at_cancel numeric(12,2), policy_public_id uuid, policy_version integer, reason TEXT, refund_due numeric(12,2), refund_status varchar(20) not null check (refund_status in ('NOT_APPLICABLE','PENDING','PARTIALLY_PAID','PAID')), revised_net_profit numeric(12,2), sunk_vendor_cost numeric(12,2), system_computed_charge_base numeric(12,2), tcs_retained numeric(12,2), total_retained numeric(12,2), vendor_recoverable numeric(12,2), primary key (id), constraint uk_booking_cancellation_booking unique (booking_id));
CREATE TABLE IF NOT EXISTS booking_cancellations_aud (id bigint not null, rev integer not null, revtype smallint, applied_band_min_days integer, applied_deduction_type varchar(10) check (applied_deduction_type in ('PERCENT','FLAT')), applied_deduction_value numeric(12,2), base_considered numeric(12,2), booking_code varchar(20), booking_id bigint, cancel_date date, cancel_scope varchar(10) check (cancel_scope in ('FULL','PARTIAL')), cancelled_at timestamp(6), cancelled_by_email varchar(255), cancelled_by_user_id bigint, credit_note_doc_public_id uuid, credit_note_number varchar(30), customer_balance_owed numeric(12,2), customer_owes boolean, days_before_departure integer, final_charge_base numeric(12,2), gst_on_charge numeric(12,2), lead_action varchar(30) check (lead_action in ('MOVE_TO_LEAD','PERMANENT_DELETE_LEAD')), no_policy boolean, overridden_by_user_id bigint, override_applied boolean, override_reason TEXT, paid_at_cancel numeric(12,2), policy_public_id uuid, policy_version integer, reason TEXT, refund_due numeric(12,2), refund_status varchar(20) check (refund_status in ('NOT_APPLICABLE','PENDING','PARTIALLY_PAID','PAID')), revised_net_profit numeric(12,2), sunk_vendor_cost numeric(12,2), system_computed_charge_base numeric(12,2), tcs_retained numeric(12,2), total_retained numeric(12,2), vendor_recoverable numeric(12,2), primary key (rev, id));
