CREATE TABLE IF NOT EXISTS booking_reminders (id bigint generated by default as identity, created_at timestamp(6) not null, created_by varchar(255), deleted_at timestamp(6), deleted_by varchar(255), public_id uuid not null unique, updated_at timestamp(6) not null, updated_by varchar(255), tenant_id bigint not null, amount float(53), booking_code varchar(50) not null, customer_name varchar(255) not null, destination varchar(255), message varchar(1000), phone varchar(30), reminder_date timestamp(6) with time zone not null, reminder_type varchar(20) not null check (reminder_type in ('Payment_due','Final_payment','Document','Visa','Travel_date','Itinerary')), status varchar(15) not null check (status in ('Pending','Sent','Completed')), travel_date timestamp(6) with time zone, primary key (id));
