CREATE TABLE IF NOT EXISTS booking_service_items (id bigint generated by default as identity, created_at timestamp(6) not null, created_by varchar(255), deleted_at timestamp(6), deleted_by varchar(255), public_id uuid not null unique, updated_at timestamp(6) not null, updated_by varchar(255), tenant_id bigint not null, booking_id bigint not null, confirmation_number varchar(100), cost numeric(12,2), description TEXT, end_date date, notes TEXT, service_date date, service_type varchar(60), status varchar(20) not null check (status in ('PENDING','CONFIRMED','CANCELLED')), title varchar(200) not null, vendor_cost numeric(12,2), vendor_id bigint, vendor_name_snapshot varchar(200), vendor_public_id uuid, primary key (id));
